import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {resolve} from 'node:path';
import {prepareProjectSourceOriginCst} from '../prepare-project-source-origin-cst.mjs';
import {createRustConcreteSyntaxStage,createRustConcreteSyntaxStages as original} from '../forward-concrete-syntax.mjs';
import {createRustConcreteSyntaxSourceStages as sourceOrigin} from '../forward-source-origin-concrete-syntax.mjs';
import {readRustConcreteSyntaxMeta} from '../forward-concrete-syntax.mjs';
import {ownershipCompiler} from '../js-to-rust/vendor/module-syntax.mjs';
import {verifyNativeCopiedModuleBindings} from '../source-copy-native-bindings.mjs';
import {resolveModuleGraph} from '../project.mjs';

test('complete source producer retains original APIs and both serialized phases and full inverses',{timeout:60000},()=>{
 const proposal=prepareProjectSourceOriginCst();assert.equal(proposal.files.length,2);
 assert.equal(proposal.typescriptVersion,'5.9.3');assert.equal(proposal.originalBoundsChanged,false);
 assert.equal(proposal.privateNativeSourceJsonOnly,true);assert.equal(proposal.semanticAuthority,false);
 const bindings=verifyNativeCopiedModuleBindings(ownershipCompiler(),proposal.files.map(row=>({path:resolve(row.path),source:row.after})));
 for(const [at,row]of proposal.files.entries()){
  assert.equal(readFileSync(row.path,'utf8'),row.after);assert.equal(row.current,row.after);
  assert.equal(row.inverse,row.before);assert.equal(row.equation.inverse,row.before);
  assert.equal(bindings[at].nativeSemanticScopeChecked,true);
  assert.deepEqual(row.equation.stages.map(stage=>stage.phase),['language','repository']);
  for(const stage of row.equation.stages){
   assert.equal(readRustOrJs(stage.beforeMeta),stage.before);
   assert.equal(readRustOrJs(stage.afterMeta),stage.after);assert.equal(stage.inverse,stage.before);
  }
  if(row.originalPath)assert.equal(readFileSync(row.originalPath,'utf8'),row.before);
 }
});
function readRustOrJs(meta){return JSON.parse(meta).source;}

test('source-origin partitioning preserves every full original Unicode trivia and malformed document',{timeout:60000},()=>{
 const sources=Array.from({length:258},(_,at)=>`// Ω😀 ${at}\r\npub fn f${at}()->u8{7u8}\r\n`);
 sources.splice(20,0,'// '+'x'.repeat(66000)+'\n','\ufeff// \ud800\r\npub fn lone(){}','mod broken {','pub fn broken(){"unterminated','pub fn broken(){/*unterminated');
 const result=sourceOrigin(sources);assert.deepEqual(result,original(sources));
 for(const at of [0,20,21,22,23,24,255,256,result.length-1]){
  assert.deepEqual(result[at],createRustConcreteSyntaxStage(sources[at]));
  assert.equal(readRustConcreteSyntaxMeta(JSON.stringify(result[at].document)).source,sources[at]);
  assert.deepEqual(result[at].document.authority,{type:false,owner:false,executable:false});
 }
});

test('independent aggregate partitions retain dense documents and original absolute refusals',{timeout:60000},()=>{
 const source='a '.repeat(40000),expected=createRustConcreteSyntaxStage(source);
 const result=sourceOrigin([source,source,source]);assert.equal(result.length,3);
 for(const stage of result)assert.deepEqual(stage,expected);
 assert.deepEqual(result,original([source,source,source]));
 for(const sources of [[' '.repeat(2097153)],['pub fn valid(){}',null],[{source:'',document:{authority:{executable:true}}}]]){
  assert.throws(()=>original(sources),TypeError);assert.throws(()=>sourceOrigin(sources),TypeError);
 }
});

test('actual graph uses reconstructed complete physical sources and keeps callback order and inline spans',{timeout:60000},()=>{
 const files={'src/lib.rs':'// Ω😀\r\nmod child;mod nested{pub fn answer()->u8{9}}',
  'src/child.rs':'pub fn answer()->u8{7}'};
 const calls=[],events=[],graph=resolveModuleGraph({entry:'src/lib.rs',paths:Object.keys(files),readSource(path){calls.push(path);return files[path];}},event=>events.push(event));
 assert.deepEqual(calls,Object.keys(files));assert.deepEqual(graph.diagnostics,[]);
 assert.deepEqual(graph.modules.map(module=>module.path),[[],['child'],['nested']]);
 assert.deepEqual(graph.concreteSyntaxMeta.map(row=>row.source),calls);
 for(const row of graph.concreteSyntaxMeta)assert.deepEqual(row.document,createRustConcreteSyntaxStage(files[row.source]).document);
 assert.equal(events.filter(event=>event.state==='start').length,3);
 assert.equal(events.filter(event=>event.state==='end').length,3);
 const nested=graph.modules[2];assert.equal(nested.source,files['src/lib.rs']);assert.equal(nested.offset,0);
 files['src/child.rs']='// changed full bytes\r\npub fn changed()->u8{11}';
 const next=resolveModuleGraph({entry:'src/lib.rs',paths:Object.keys(files),readSource:path=>files[path]});
 assert.equal(next.modules[1].source,files['src/child.rs']);assert.notDeepEqual(next.concreteSyntaxMeta[1],graph.concreteSyntaxMeta[1]);
});

test('changed JSON and traversal hosts refuse before running replacement callbacks',{timeout:60000},()=>{
 let calls=0;
 for(const [owner,key]of [[JSON,'parse'],[JSON,'stringify'],[Array.prototype,'entries']]){
  const field=Object.getOwnPropertyDescriptor(owner,key);
  try{
   Object.defineProperty(owner,key,{...field,value:function(){calls++;throw Error('replacement invoked');}});
   assert.throws(()=>sourceOrigin(['pub fn one(){}','pub fn two(){}']),TypeError);
  }finally{Object.defineProperty(owner,key,field);}
 }
 assert.equal(calls,0);assert.deepEqual(sourceOrigin(['pub fn current(){}']),original(['pub fn current(){}']));
});

import test from 'node:test';
import assert from 'node:assert/strict';
import {createRustConcreteSyntaxStage,createRustConcreteSyntaxStages} from '../forward-concrete-syntax.mjs';
import {readRustConcreteSyntaxMeta} from '../forward-concrete-syntax.mjs';
import {resolveModuleGraph} from '../project.mjs';
import {originalSourceModuleItems} from '../source-module-views.mjs';
import {PRODUCTION_PROFILE} from '../cfg-profile.mjs';

test('bounded ingress retains every complete source and independent CST inverse across partitions',{timeout:60000},()=>{
 const sources=Array.from({length:258},(_,at)=>`// Ω😀 ${at}\r\npub fn f${at}()->u8{7u8}\r\n`);
 sources.splice(20,0,'// '+ 'x'.repeat(66000)+'\n');
 const stages=createRustConcreteSyntaxStages(sources);
 assert.equal(stages.length,sources.length);
 for(let at=0;at<sources.length;at++){
  assert.equal(stages[at].source,sources[at]);
  assert.equal(stages[at].document.source,sources[at]);
 }
 for(const at of [0,20,255,256,stages.length-1]){
  assert.deepEqual(stages[at],createRustConcreteSyntaxStage(sources[at]));
  assert.equal(readRustConcreteSyntaxMeta(JSON.stringify(stages[at].document)).source,sources[at]);
 }
});

test('dense batches retain complete original documents without raising any original bound',{timeout:60000},()=>{
 const source='a '.repeat(40000),expected=createRustConcreteSyntaxStage(source);
 const stages=createRustConcreteSyntaxStages([source,source,source]);
 assert.equal(stages.length,3);for(const stage of stages)assert.deepEqual(stage,expected);
 assert.throws(()=>createRustConcreteSyntaxStages([' '.repeat(2097153)]),TypeError);
});

test('only reachable physical files cross ingress and inline views retain original coordinates',{timeout:60000},()=>{
 const files={
  'src/lib.rs':'// full Ω😀\r\nmod child;#[cfg(test)]mod absent;mod nested{pub fn value()->u8{9u8}}\r\n',
  'src/child.rs':'pub fn value()->u8{7u8}\n',
  'src/absent.rs':'invalid }',
 };
 const calls=[],events=[],graph=resolveModuleGraph({entry:'src/lib.rs',paths:Object.keys(files),compilationProfile:PRODUCTION_PROFILE,readSource(file){calls.push(file);return files[file];}},row=>events.push(row));
 assert.deepEqual(calls,['src/lib.rs','src/child.rs']);assert.deepEqual(graph.diagnostics,[]);
 assert.deepEqual(graph.modules.map(row=>row.path),[[],['child'],['nested']]);
 assert.deepEqual(graph.concreteSyntaxMeta.map(row=>row.source),calls);
 for(const row of graph.concreteSyntaxMeta)assert.deepEqual(row.document,createRustConcreteSyntaxStage(files[row.source]).document);
 const inline=graph.modules.find(row=>row.path[0]==='nested');
 assert.equal(inline.source,files['src/lib.rs']);assert.equal(inline.offset,0);
 const items=originalSourceModuleItems(inline);assert.equal(items.length,1);assert.equal(items[0].term,'fn');
 assert.ok(items[0].start>files['src/lib.rs'].indexOf('mod nested'));
 assert.equal(events.filter(row=>row.state==='start').length,3);
 assert.equal(events.filter(row=>row.state==='end').length,3);
});

test('fresh graph calls transport changed full bytes and retain conditional candidates',{timeout:60000},()=>{
 const files={'src/lib.rs':'#[cfg(unproved)]mod child;','src/child.rs':'pub fn first()->u8{7u8}'};
 const options={entry:'src/lib.rs',paths:Object.keys(files),readSource:file=>files[file]};
 const before=resolveModuleGraph(options);files['src/child.rs']='// changed Ω\npub fn second()->u8{9u8}';
 const after=resolveModuleGraph(options);
 assert.equal(after.modules[1].source,files['src/child.rs']);
 assert.notDeepEqual(after.concreteSyntaxMeta[1].document,before.concreteSyntaxMeta[1].document);
 assert.equal(after.modules[1].configurationCondition,'unknown');assert.ok(after.diagnostics.length);
 assert.equal(readRustConcreteSyntaxMeta(JSON.stringify(after.concreteSyntaxMeta[1].document)).source,files['src/child.rs']);
});

test('complete graph ingress consumes iterable path inputs once',{timeout:60000},()=>{
 // Root-only graphs accepted iterable paths before batched ingress. External
 // module planning separately retains its existing bounded-array contract.
 const files={'src/lib.rs':'pub fn value()->u8{7u8}'};
 const keys=Object.keys(files),base={entry:'src/lib.rs',readSource:file=>files[file]};
 const expected=resolveModuleGraph({...base,paths:keys});
 let iterations=0;
 const once={
  [Symbol.iterator](){iterations++;assert.equal(iterations,1);return keys[Symbol.iterator]();},
 };
 for(const paths of [new Set(keys),(function*(){yield*keys;})(),once]){
  const calls=[],actual=resolveModuleGraph({...base,paths,readSource(file){calls.push(file);return files[file];}});
  assert.deepEqual(calls,keys);
  assert.deepEqual(actual.concreteSyntaxMeta,expected.concreteSyntaxMeta);
  assert.deepEqual(actual.modules.map(({source,path,offset})=>({source,path,offset})),expected.modules.map(({source,path,offset})=>({source,path,offset})));
  assert.deepEqual(actual.edges,expected.edges);assert.deepEqual(actual.diagnostics,expected.diagnostics);
 }
 assert.equal(iterations,1);
 assert.throws(()=>resolveModuleGraph({...base,paths:undefined}),/crate entrypoint is not tracked/u);
 const reads=[],external=resolveModuleGraph({entry:'src/lib.rs',paths:new Set(['src/lib.rs','src/child.rs']),readSource(file){reads.push(file);return 'mod child;';}});
 assert.deepEqual(reads,['src/lib.rs']);assert.equal(external.modules.length,1);
 assert.ok(external.diagnostics.some(row=>row.message.includes('tracked path list exceeds its bound')));
});

test('malformed source retains the original diagnostic CST without semantic authority',{timeout:60000},()=>{
 for(const source of ['mod broken {','pub fn broken(){"unterminated','pub fn broken(){/*unterminated']){
  const expected=createRustConcreteSyntaxStage(source),stages=createRustConcreteSyntaxStages(['pub fn valid(){}',source]);
  assert.deepEqual(stages[1],expected);assert.ok(expected.document.diagnostics.length);
  const graph=resolveModuleGraph({entry:'lib.rs',paths:['lib.rs'],readSource:()=>source});
  assert.deepEqual(graph.concreteSyntaxMeta[0].document,expected.document);assert.ok(graph.diagnostics.length);
 }
 assert.throws(()=>createRustConcreteSyntaxStages(['pub fn valid(){}',null]),TypeError);
 assert.throws(()=>resolveModuleGraph({entry:'lib.rs',paths:['lib.rs'],readSource:()=>({source:'pub fn valid(){}'})}),TypeError);
});
